"""Portable updates use generated byte files, never a real application or photo library."""
import hashlib
import io
import json
from pathlib import Path
from types import SimpleNamespace
import tempfile
import threading
import unittest
from unittest.mock import Mock,patch
from urllib.request import Request

from photo_review.self_update import (StagedUpdate,stage_update,start_helper,apply_update,
    file_hash,asset_url,ReleaseRedirects,verify_update_signature,fresh_environment,cleanup_old_updates)
from photo_review.updates import Update
from photo_review.version import REPOSITORY


class Response(io.BytesIO):
    def __init__(self,body,url):super().__init__(body);self.url=url
    def geturl(self):return self.url


class PortableUpdateTests(unittest.TestCase):
    def setUp(self):
        self.temp=tempfile.TemporaryDirectory();self.root=Path(self.temp.name)
        self.target=self.root/'Photo Review.exe';self.old=b'generated original EXE bytes';self.new=b'generated replacement EXE bytes'
        self.target.write_bytes(self.old);self.cache=self.root/'updates'
        base=f'https://github.com/{REPOSITORY}/releases/download/v2.0/'
        self.update=Update('2.0',base,base+'PhotoReview.exe','Changes',base+'release-manifest.json',len(self.new))
        self.manifest=dict(version='2.0',repository=REPOSITORY,asset='PhotoReview.exe',size=len(self.new),sha256=hashlib.sha256(self.new).hexdigest())
        self.urls=[]
    def tearDown(self):self.temp.cleanup()
    def opener(self,url):
        self.urls.append(url)
        return Response(json.dumps(self.manifest).encode() if url.endswith('.json') else self.new,url)
    def stage(self,**kwargs):
        return stage_update(self.update,self.target,self.cache,opener=self.opener,signature_verifier=lambda *a:None,**kwargs)
    def plan(self,staged,resume=None):
        launcher=Mock();start_helper(staged,resume=resume,launcher=launcher)
        return staged.helper.parent/'transaction.json'
    def test_verified_download_does_not_change_running_exe(self):
        progress=[];staged=self.stage(progress=progress.append)
        self.assertEqual(self.target.read_bytes(),self.old);self.assertEqual(staged.candidate.read_bytes(),self.new)
        self.assertEqual(staged.helper.read_bytes(),self.old)
        self.assertEqual(self.urls,[self.update.manifest_url,self.update.download_url])
        self.assertTrue(any('MB/s' in line for line in progress))
    def test_cancel_and_checksum_failure_leave_original_and_no_staged_exe(self):
        cancel=threading.Event()
        with self.assertRaises(InterruptedError):self.stage(cancel=cancel,progress=lambda text:cancel.set())
        self.assertEqual(self.target.read_bytes(),self.old);self.assertEqual(list(self.cache.iterdir()),[])
        self.manifest['sha256']='0'*64
        with self.assertRaisesRegex(ValueError,'checksum'):self.stage()
        self.assertEqual(list(self.cache.iterdir()),[]);self.assertEqual(self.target.read_bytes(),self.old)
    def test_bad_manifest_never_downloads_exe(self):
        self.manifest['version']='9.0'
        with self.assertRaisesRegex(ValueError,'manifest'):self.stage()
        self.assertEqual(self.urls,[self.update.manifest_url]);self.assertFalse(self.cache.exists())
    def test_unwritable_target_stops_before_network_or_restart(self):
        with patch('photo_review.self_update.tempfile.NamedTemporaryFile',side_effect=PermissionError('read only')):
            with self.assertRaises(PermissionError):self.stage()
        self.assertEqual(self.urls,[]);self.assertEqual(self.target.read_bytes(),self.old)
    def test_helper_waits_then_replaces_and_resumes_saved_review(self):
        staged=self.stage();resume=self.root/'review draft.json';resume.write_text('{}');plan=self.plan(staged,resume)
        calls=[]
        def wait(pid):self.assertEqual(self.target.read_bytes(),self.old);calls.append('wait')
        def launch(args,**kw):self.assertEqual(self.target.read_bytes(),self.new);calls.append(args)
        result=apply_update(plan,staged.helper,wait=wait,launcher=launch)
        self.assertEqual(calls,['wait',[str(self.target),'--resume-review',str(resume)]])
        self.assertEqual(result['status'],'installed');self.assertEqual(staged.helper.read_bytes(),self.old)
        self.assertFalse(staged.candidate.exists());self.assertFalse(list(self.root.glob('*.previous-*')))
    def test_launch_failure_restores_previous_exe(self):
        staged=self.stage();plan=self.plan(staged)
        with self.assertRaisesRegex(OSError,'blocked'):
            apply_update(plan,staged.helper,wait=lambda pid:None,launcher=Mock(side_effect=OSError('blocked')))
        self.assertEqual(self.target.read_bytes(),self.old);self.assertFalse(list(self.root.glob('*.new-*')))
        self.assertFalse(list(self.root.glob('*.previous-*')))
    def test_tampering_and_parent_timeout_never_replace_installed_exe(self):
        staged=self.stage();plan=self.plan(staged);staged.candidate.write_bytes(b'tampered');wait=Mock()
        with self.assertRaisesRegex(ValueError,'validation'):apply_update(plan,staged.helper,wait=wait)
        wait.assert_not_called();self.assertEqual(self.target.read_bytes(),self.old)
        staged.candidate.write_bytes(self.new)
        with self.assertRaises(TimeoutError):apply_update(plan,staged.helper,wait=Mock(side_effect=TimeoutError('still running')))
        self.assertEqual(self.target.read_bytes(),self.old)
    def test_changed_installed_exe_is_not_overwritten(self):
        staged=self.stage();plan=self.plan(staged);self.target.write_bytes(b'other update installed')
        with self.assertRaisesRegex(ValueError,'installed EXE changed'):apply_update(plan,staged.helper,wait=lambda pid:None)
        self.assertEqual(self.target.read_bytes(),b'other update installed')
    def test_download_redirects_stay_on_https_github_asset_hosts(self):
        self.assertEqual(asset_url('https://release-assets.githubusercontent.com/file'),'https://release-assets.githubusercontent.com/file')
        for url in ('http://github.com/file','https://github.com.evil.test/file','https://user:pass@github.com/file','file:///C:/file.exe'):
            with self.subTest(url=url),self.assertRaises(ValueError):asset_url(url)
        with self.assertRaises(ValueError):ReleaseRedirects().redirect_request(Request(self.update.download_url),None,302,'',{},'https://example.com/file.exe')
    def test_signed_build_cannot_downgrade_to_unsigned_or_other_publisher(self):
        def runner(values):return Mock(return_value=SimpleNamespace(stdout=json.dumps(values)))
        verify_update_signature(self.target,self.target,runner=runner(dict(oldSubject=None,newSubject=None,newStatus='NotSigned')))
        verify_update_signature(self.target,self.target,runner=runner(dict(oldSubject='Publisher',newSubject='Publisher',newStatus='Valid')))
        for values in (dict(oldSubject='Publisher',newSubject=None,newStatus='NotSigned'),dict(oldSubject='Publisher',newSubject='Other',newStatus='Valid')):
            with self.assertRaisesRegex(ValueError,'publisher'):verify_update_signature(self.target,self.target,runner=runner(values))
    def test_downloaded_exe_metadata_must_match_the_release(self):
        values=dict(oldSubject=None,newSubject=None,newStatus='NotSigned',product='Photo Review',fileVersion='2.0.0.0',productVersion='2.0.0.0')
        runner=Mock(return_value=SimpleNamespace(stdout=json.dumps(values)))
        verify_update_signature(self.target,self.target,version='2.0',runner=runner)
        with self.assertRaisesRegex(ValueError,'selected PhotoReview version'):
            verify_update_signature(self.target,self.target,version='2.1',runner=runner)
    def test_signature_reader_uses_windows_modules_without_changing_parent_environment(self):
        runner=Mock(return_value=SimpleNamespace(stdout='{"oldSubject":null,"newSubject":null,"newStatus":"NotSigned"}'))
        with patch.dict('os.environ',{'PSMODULEPATH':'a PowerShell 7 module directory'}):
            verify_update_signature(self.target,self.target,runner=runner)
            self.assertEqual(__import__('os').environ['PSMODULEPATH'],'a PowerShell 7 module directory')
        environment=runner.call_args.kwargs['env']
        self.assertNotIn('PSMODULEPATH',environment);self.assertTrue(environment['PSModulePath'].endswith('Modules'))
    def test_helper_launch_uses_argument_list_and_fresh_bootstrap_environment(self):
        staged=self.stage();launcher=Mock()
        with patch.dict('os.environ',{'NUITKA_ONEFILE_PARENT':'123','NUITKA_ORIGINAL_ARGV0':'old.exe'}):
            start_helper(staged,launcher=launcher)
        args,kwargs=launcher.call_args
        self.assertEqual(args[0],[str(staged.helper),'--apply-update',str(staged.helper.parent/'transaction.json')])
        self.assertNotIn('NUITKA_ONEFILE_PARENT',kwargs['env']);self.assertNotIn('NUITKA_ORIGINAL_ARGV0',kwargs['env'])
    def test_cleanup_only_removes_known_completed_update_files(self):
        finished=self.cache/('a'*32);finished.mkdir(parents=True)
        (finished/'result.json').write_text('{"status":"installed"}');(finished/'PhotoReview.update-helper.exe').write_bytes(self.old)
        (finished/'personal note.txt').write_text('keep me')
        unfinished=self.cache/('b'*32);unfinished.mkdir();(unfinished/'PhotoReview.new.exe').write_bytes(self.new)
        cleanup_old_updates(self.cache,keep=0)
        self.assertEqual((finished/'personal note.txt').read_text(),'keep me')
        self.assertTrue((unfinished/'PhotoReview.new.exe').exists());self.assertFalse((finished/'PhotoReview.update-helper.exe').exists())
